using static StrataLint.Scribe.DefinitionDsl;

namespace StrataLint.Scribe.Blueprint.D5.S3.ConceptDynamics.Coding.PositiveRecoding;

internal sealed class ActualRelabelResidueDocument : IScribeDocumentDefinition
{
    public DocumentDefinition Create() => DocumentDefinition.Create(ScribeNode.Create(
        "Actual relabel row matrices equal the reduced forward gyration.",
        H("Actual relabel row matrices equal the reduced forward gyration"),
        Blocks(
            Paragraph(Text("actual_Q_mul_P derives the target matrix B from the actual vertex and edge equivalences of r. rows_standard states that the source row index precedes the target column index. reindex_rows identifies the forward row matrix with counts (P e); backward_map and backward_rows identify the other factor with counts (Q e A). Both factors belong to the literal row convention.")),
            Paragraph(Text("For all n,m,d, with NeZero d and hd : 3 ∣ d, relabel_residue equates the actual relabelEdge weight in the two standard bases with the reduction of timed r gyration from ZMod d to ZMod 3. The edge bijection supplies the matrix identity; no desired equality or literal signed eight-by-eight graph matrix is an additional premise. Zero dimensions and arbitrary parallel-edge permutations remain allowed.")),
            Paragraph(Text("These constructions and identities are repository-derived. Their provenance does not assert literature novelty.")),
            Describe.Lean(DescribeId.Create("positive-recoding-actualrelabelresidue-reindex-rows"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelResidue.reindex_rows"), H("reindex_rows"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("In the standard source and target bases, the row matrix of vertex reindexing is the counted permutation factor. This fixes the orientation of the forward factor."))), DescribeRole.Theorem),
            Describe.Lean(DescribeId.Create("positive-recoding-actualrelabelresidue-relabel-residue"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelResidue.relabel_residue"), H("relabel_residue"), StatementSource.WithoutFormula(), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The exact requested comparison, for every finite n,m, including zero, and every nonzero d with 3 dividing d. There is no added equality premise."))), DescribeRole.Theorem),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelresidue-actual-q-mul-p"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelResidue.actual_Q_mul_P"), H("actual_Q_mul_P"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("This coefficient equality uses the ACTUAL edge bijection, so arbitrary parallel-edge permutations have not been discarded from the input.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelresidue-rows-standard"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelResidue.rows_standard"), H("rows_standard"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Literal standard-basis entries, with the ROW index first.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelresidue-rows-right-standard"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelResidue.rows_right_standard"), H("rows_right_standard"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("The row matrix of right multiplication in the standard bases is the given rectangular matrix. It is used to identify the backward factor without a transpose.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelresidue-backward-map"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelResidue.backward_map"), H("backward_map"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Graph time after inverse vertex reindexing is right multiplication by the counted complementary factor Q. This identifies the actual backward linear map.")))),
            Describe.Remark(DescribeId.Create("positive-recoding-actualrelabelresidue-backward-rows"), DeclarationHandle.Create("D5/S3/ConceptDynamics/Coding/PositiveRecoding/ActualRelabelResidue.backward_rows"), H("backward_rows"), AssessedProvenance.FromRepo(), Blocks(Paragraph(Text("Taking standard row coordinates of backward_map yields counts of Q. Together with reindex_rows it identifies both factors in the relabel cochain.")))))));
}
